<script>
const bulkForm=document.getElementById('bulk-trip-form');
function updateBulkSelection(){const boxes=[...bulkForm.querySelectorAll('[name="parcel_ids[]"]:checked')];const stops=new Set(boxes.map(x=>x.dataset.destination));document.getElementById('bulk-selection-count').textContent=boxes.length+' parcels · '+stops.size+' destination centers selected';document.getElementById('bulk-trip-submit').disabled=boxes.length===0||stops.size>10||!bulkForm.querySelector('[name="driver_id"]').value;}
bulkForm.addEventListener('change',updateBulkSelection);
</script>
